import"./chunk-VC46IEJQ.js";var e=(t,o,s,h,l,r,n,i,a)=>({name:{en:t[0],zh:t[1]},desc:{en:o[0],zh:o[1]},tour:{en:s[0],zh:s[1]},...a?{spoiler:{en:a[0],zh:a[1]}}:{},source:{confidence:h,refs:l,book:{en:r[0],zh:r[1]},unknown:{en:n[0],zh:n[1]},interpretation:{en:i[0],zh:i[1]}}}),d={id:"volantis",intro:{en:"Oldest and proudest of the Free Cities, Volantis straddles the mouth of the Rhoyne: the black-walled old city of the Valyrian-blooded families on the east bank, a sprawling trading city on the west, joined by the Long Bridge. Hot, humid, crowded with ships and built on slavery.",zh:"\u74E6\u5170\u63D0\u65AF\u662F\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E2D\u6700\u53E4\u8001\u3001\u6700\u9A84\u50B2\u7684\u4E00\u5EA7\uFF0C\u6A2A\u8DE8\u6D1B\u6069\u6CB3\u53E3\uFF1A\u4E1C\u5CB8\u662F\u9ED1\u5899\u73AF\u7ED5\u3001\u74E6\u96F7\u5229\u4E9A\u8840\u7EDF\u4E16\u5BB6\u805A\u5C45\u7684\u65E7\u57CE\uFF0C\u897F\u5CB8\u662F\u94FA\u5C55\u5F00\u6765\u7684\u5546\u8D38\u57CE\u533A\uFF0C\u4E24\u5CB8\u7531\u957F\u6865\u76F8\u8FDE\u3002\u8FD9\u91CC\u6E7F\u70ED\u96BE\u8010\uFF0C\u6E2F\u4E2D\u821F\u696B\u5982\u6797\uFF0C\u6574\u5EA7\u57CE\u5EFA\u7ACB\u5728\u5974\u96B6\u5236\u4E4B\u4E0A\u3002"},notes:{en:"From A Dance with Dragons and TWOIAF: the Black Walls, the Long Bridge, the harbour at the Rhoyne mouth, the great red Temple of the Lord of Light and its Fiery Hand, the Merchant's House inn on the west bank, three annually elected triarchs, the tiger and elephant factions, and slaves outnumbering the free, with tattooed faces. Invented here: the street plan, building forms, all positions, the triarchs' hall and the districts. No cutaway: no interior is described well enough to build one.",zh:"\u51FA\u81EA\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E0E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\uFF1A\u9ED1\u5899\u3001\u957F\u6865\u3001\u6D1B\u6069\u6CB3\u53E3\u7684\u6E2F\u6E7E\u3001\u5B8F\u5927\u7684\u5149\u4E4B\u738B\u7EA2\u795E\u5E99\u53CA\u5176\u70C8\u7130\u4E4B\u624B\u3001\u897F\u5CB8\u7684\u5546\u4EBA\u4E4B\u5BB6\u5BA2\u6808\u3001\u6BCF\u5E74\u9009\u4E3E\u7684\u4E09\u4F4D\u6267\u653F\u5B98\u3001\u864E\u515A\u4E0E\u8C61\u515A\u4E4B\u4E89\uFF0C\u4EE5\u53CA\u4EBA\u6570\u8FDC\u8D85\u81EA\u7531\u6C11\u3001\u8138\u4E0A\u523A\u9752\u7684\u5974\u96B6\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u8857\u9053\u5E03\u5C40\u3001\u5EFA\u7B51\u9020\u578B\u3001\u4E00\u5207\u65B9\u4F4D\u3001\u6267\u653F\u5B98\u5927\u5385\u4E0E\u5404\u57CE\u533A\u3002\u4E0D\u4F5C\u5256\u9762\uFF1A\u4E66\u4E2D\u6CA1\u6709\u8DB3\u4EE5\u590D\u539F\u7684\u5185\u90E8\u63CF\u5199\u3002"},tour:["rhoyne-mouth","harbour","long-bridge","merchants-house","slave-markets","black-walls","old-volantis","triarchs-hall","red-temple","valyrian-road"],sources:[{ref:"adwd",checked:"memory",note:{en:"The Volantis chapters (crossing the Long Bridge, the Merchant's House, a triarch election, red priests preaching, tattooed slaves) recalled from memory, not re-read.",zh:"\u74E6\u5170\u63D0\u65AF\u7AE0\u8282\uFF08\u8FC7\u957F\u6865\u3001\u5546\u4EBA\u4E4B\u5BB6\u3001\u6267\u653F\u5B98\u9009\u4E3E\u3001\u7EA2\u888D\u50E7\u5E03\u9053\u3001\u523A\u9752\u5974\u96B6\uFF09\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Black Walls (fused black stone, about 200 ft high, six four-horse chariots abreast on top), the Long Bridge as a Wonder Made by Man, the Merchant's House as the largest inn with a view of the bridge and the walls, the red temple (Fiery Hand, about three times the Great Sept), the demon road east to Meereen: web-search summaries; pages not fetched.",zh:"\u9ED1\u5899\uFF08\u9ED1\u8272\u7194\u77F3\uFF0C\u9AD8\u7EA6\u4E8C\u767E\u5C3A\uFF0C\u5899\u9876\u53EF\u5BB9\u516D\u8F86\u56DB\u9A6C\u6218\u8F66\u5E76\u9A7E\uFF09\u3001\u4F4D\u5217\u4EBA\u9020\u5947\u89C2\u7684\u957F\u6865\u3001\u5546\u4EBA\u4E4B\u5BB6\u662F\u57CE\u4E2D\u6700\u5927\u5BA2\u6808\u4E14\u53EF\u671B\u89C1\u957F\u6865\u4E0E\u9ED1\u5899\u3001\u7EA2\u795E\u5E99\uFF08\u70C8\u7130\u4E4B\u624B\uFF0C\u7EA6\u4E3A\u8D1D\u52D2\u5927\u5723\u5802\u4E09\u500D\uFF09\u3001\u5411\u4E1C\u901A\u5F80\u5F25\u6797\u7684\u6076\u9B54\u4E4B\u8DEF\uFF1A\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"Volantene history drawn from memory of the book; not re-checked.",zh:"\u74E6\u5170\u63D0\u65AF\u5386\u53F2\u51ED\u5BF9\u8BE5\u4E66\u7684\u8BB0\u5FC6\uFF0C\u672A\u518D\u6838\u5BF9\u3002"}}],landmarks:{"rhoyne-mouth":e(["Rhoyne Mouth","\u6D1B\u6069\u6CB3\u53E3"],["The great river widens into a broad, silty mouth, busy with sails from across the known world.","\u5927\u6CB3\u5728\u6B64\u5C55\u5F00\u4E3A\u5BBD\u9614\u6D51\u6D4A\u7684\u6CB3\u53E3\uFF0C\u6765\u81EA\u5DF2\u77E5\u4E16\u754C\u5404\u5730\u7684\u5E06\u5F71\u5F80\u6765\u4E0D\u7EDD\u3002"],["The Rhoyne ends here, and many eastern trade routes with it.","\u6D1B\u6069\u6CB3\u5728\u6B64\u5165\u6D77\uFF0C\u8BB8\u591A\u4E1C\u65B9\u5546\u8DEF\u4E5F\u5728\u6B64\u4EA4\u6C47\u3002"],"high",["twoiaf","maps"],["Volantis stands where the Rhoyne meets the sea; its harbour made it a great trading power.","\u74E6\u5170\u63D0\u65AF\u4F4D\u4E8E\u6D1B\u6069\u6CB3\u5165\u6D77\u5904\uFF0C\u51ED\u501F\u6E2F\u53E3\u6210\u4E3A\u5546\u8D38\u5F3A\u6743\u3002"],["The exact shape of the delta and its shoals.","\u6CB3\u53E3\u4E09\u89D2\u6D32\u4E0E\u6D45\u6EE9\u7684\u786E\u5207\u5F62\u72B6\u3002"],["A broad funnel-shaped estuary with muddy banks and palm groves.","\u5587\u53ED\u5F62\u7684\u5BBD\u9614\u6CB3\u53E3\uFF0C\u6CE5\u5CB8\u4E0E\u68D5\u6988\u6797\u3002"]),harbour:e(["Harbour","\u6E2F\u53E3"],["Quays, piers and warehouses line both banks; cogs, galleys and barges crowd the water.","\u4E24\u5CB8\u7801\u5934\u3001\u6808\u6865\u4E0E\u4ED3\u5E93\u6797\u7ACB\uFF0C\u67EF\u514B\u8239\u3001\u6868\u5E06\u8239\u4E0E\u9A73\u8239\u6324\u6EE1\u6C34\u9762\u3002"],["Ships of every flag wait their turn at the piers.","\u6302\u7740\u5404\u8272\u65D7\u5E1C\u7684\u8239\u53EA\u5728\u6808\u6865\u524D\u6392\u961F\u7B49\u5019\u3002"],"medium",["adwd","twoiaf"],["A busy harbour with heavy shipping, including slavers and ships bound for Slaver's Bay.","\u6E2F\u53E3\u7E41\u5FD9\uFF0C\u8239\u8FD0\u5174\u76DB\uFF0C\u5176\u4E2D\u4E0D\u4E4F\u8D29\u5974\u8239\u4E0E\u9A76\u5F80\u5974\u96B6\u6E7E\u7684\u8239\u53EA\u3002"],["The layout of quays, chains, lighthouses or customs houses.","\u7801\u5934\u3001\u62E6\u6E2F\u94C1\u94FE\u3001\u706F\u5854\u4E0E\u7A0E\u5173\u7684\u5E03\u5C40\u3002"],["Wooden piers along both banks with warehouses behind them.","\u4E24\u5CB8\u6728\u6808\u6865\uFF0C\u5176\u540E\u662F\u4ED3\u5E93\u3002"]),"long-bridge":e(["Long Bridge","\u957F\u6865"],["A great stone bridge joining the two halves of the city across the river, lined with shops, stalls and houses.","\u4E00\u5EA7\u6A2A\u8DE8\u6CB3\u9762\u7684\u5B8F\u4F1F\u77F3\u6865\uFF0C\u8FDE\u63A5\u57CE\u5E02\u4E24\u534A\uFF0C\u6865\u4E0A\u5E97\u94FA\u3001\u644A\u6863\u4E0E\u623F\u5C4B\u6BD4\u80A9\u800C\u7ACB\u3002"],["Cross from east to west and you leave the old blood for the crowded markets.","\u81EA\u4E1C\u5411\u897F\u8D70\u8FC7\u957F\u6865\uFF0C\u4FBF\u544A\u522B\u65E7\u8840\u7EDF\u7684\u4E16\u754C\uFF0C\u8D70\u8FDB\u62E5\u6324\u7684\u5E02\u4E95\u3002"],"high",["adwd","twoiaf","awoiaf"],["The Long Bridge joins the two halves of Volantis, is lined with shops and buildings, and is counted among the Wonders Made by Man.","\u957F\u6865\u8FDE\u63A5\u74E6\u5170\u63D0\u65AF\u4E24\u5CB8\uFF0C\u6865\u4E0A\u5EFA\u6EE1\u5E97\u94FA\u623F\u5C4B\uFF0C\u88AB\u5217\u4E3A\u4EBA\u9020\u5947\u89C2\u4E4B\u4E00\u3002"],["Its true length and exactly what stands on it.","\u786E\u5207\u957F\u5EA6\u4E0E\u6865\u4E0A\u7684\u5177\u4F53\u5EFA\u7B51\u3002"],["Sixteen shop-houses a side; the river here is far narrower than the book scale suggests.","\u6BCF\u4FA7\u5341\u516D\u95F4\u5E97\u5C4B\uFF1B\u6B64\u5904\u6CB3\u9762\u8FDC\u6BD4\u4E66\u4E2D\u5C3A\u5EA6\u7A84\u3002"],["In A Dance with Dragons Tyrion crosses it from east to west.","\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u63D0\u5229\u6602\u81EA\u4E1C\u5411\u897F\u8D70\u8FC7\u6B64\u6865\u3002"]),"merchants-house":e(["Merchant's House","\u5546\u4EBA\u4E4B\u5BB6"],["The largest inn in Volantis, on the west bank; its windows look across the Long Bridge to the Black Walls.","\u74E6\u5170\u63D0\u65AF\u6700\u5927\u7684\u5BA2\u6808\uFF0C\u4F4D\u4E8E\u897F\u5CB8\uFF0C\u7A97\u5916\u8D8A\u8FC7\u957F\u6865\u4FBF\u662F\u9ED1\u5899\u3002"],["Foreign traders lodge here, gazing across at an old city they may not enter.","\u5916\u6765\u5546\u65C5\u5728\u6B64\u6295\u5BBF\uFF0C\u9694\u6CB3\u773A\u671B\u4ED6\u4EEC\u65E0\u6743\u8E0F\u5165\u7684\u65E7\u57CE\u3002"],"medium",["adwd","awoiaf"],["A large inn for merchants and travellers on the west bank, reached from the east by the Long Bridge, with windows facing the bridge and the Black Walls.","\u897F\u5CB8\u4E00\u5EA7\u63A5\u5F85\u5546\u65C5\u7684\u5927\u5BA2\u6808\uFF0C\u4ECE\u4E1C\u5CB8\u987B\u7ECF\u957F\u6865\u624D\u5230\uFF0C\u7A97\u6237\u9762\u671D\u957F\u6865\u4E0E\u9ED1\u5899\u3002"],["Its size, form and exact site.","\u89C4\u6A21\u3001\u5F62\u5236\u4E0E\u786E\u5207\u4F4D\u7F6E\u3002"],["A two-storey plastered building near the bridge foot with two lit windows facing east; the book inn is larger.","\u6865\u5934\u9644\u8FD1\u4E00\u5EA7\u4E24\u5C42\u62B9\u7070\u5EFA\u7B51\uFF0C\u4E24\u6247\u4EAE\u706F\u7684\u7A97\u6237\u671D\u4E1C\uFF1B\u4E66\u4E2D\u7684\u5BA2\u6808\u89C4\u6A21\u66F4\u5927\u3002"]),"slave-markets":e(["Slave Markets","\u5974\u96B6\u5E02\u573A"],["Open plazas with awnings and platforms where people are sold; slaves far outnumber the free, and their faces are tattooed.","\u8BBE\u6709\u906E\u7BF7\u4E0E\u9AD8\u53F0\u7684\u5F00\u9614\u5E7F\u573A\uFF0C\u4EBA\u5728\u8FD9\u91CC\u88AB\u4E70\u5356\u3002\u5974\u96B6\u4EBA\u6570\u8FDC\u8D85\u81EA\u7531\u6C11\uFF0C\u8138\u4E0A\u90FD\u523A\u7740\u7EB9\u6837\u3002"],["In Volantis slaves outnumber the free several times over; the trade built the city.","\u5728\u74E6\u5170\u63D0\u65AF\uFF0C\u5974\u96B6\u6570\u500D\u4E8E\u81EA\u7531\u6C11\uFF0C\u8FD9\u5EA7\u57CE\u6B63\u662F\u9760\u5974\u96B6\u8D38\u6613\u5EFA\u8D77\u6765\u7684\u3002"],"medium",["adwd","twoiaf"],["Slavery is central to Volantis: slaves greatly outnumber free people and bear facial tattoos marking their role.","\u5974\u96B6\u5236\u662F\u74E6\u5170\u63D0\u65AF\u7684\u6839\u57FA\uFF1A\u5974\u96B6\u4EBA\u6570\u8FDC\u591A\u4E8E\u81EA\u7531\u6C11\uFF0C\u8138\u4E0A\u7684\u523A\u9752\u6807\u660E\u5176\u8EAB\u4EFD\u7528\u9014\u3002"],["Where exactly the markets stand.","\u5E02\u573A\u7684\u786E\u5207\u4F4D\u7F6E\u3002"],["One plaza on the west bank with stalls and platforms; no figures shown.","\u897F\u5CB8\u4E00\u5904\u8BBE\u644A\u4F4D\u4E0E\u9AD8\u53F0\u7684\u5E7F\u573A\uFF1B\u4E0D\u5448\u73B0\u4EBA\u7269\u3002"]),"black-walls":e(["Black Walls","\u9ED1\u5899"],["A vast oval of fused black stone raised by Valyria around Old Volantis, so broad that chariots race along its top.","\u74E6\u96F7\u5229\u4E9A\u4EBA\u4EE5\u7194\u878D\u9ED1\u77F3\u7B51\u6210\u7684\u5DE8\u5927\u692D\u5706\u57CE\u5899\uFF0C\u73AF\u7ED5\u65E7\u74E6\u5170\u63D0\u65AF\uFF0C\u5899\u9876\u5BBD\u9614\u5F97\u53EF\u4F9B\u6218\u8F66\u7ADE\u9A70\u3002"],["Seamless and black: the old city is walled in Valyria's own stone.","\u6F06\u9ED1\u65E0\u7F1D\uFF1A\u65E7\u57CE\u88AB\u56F4\u5728\u74E6\u96F7\u5229\u4E9A\u4EB2\u624B\u7194\u94F8\u7684\u77F3\u5899\u4E4B\u4E2D\u3002"],"high",["adwd","twoiaf","awoiaf"],["Fused black stone about two hundred feet high, wide enough for six four-horse chariots abreast; only those of old Valyrian blood may live within.","\u7194\u878D\u9ED1\u77F3\u7B51\u6210\uFF0C\u9AD8\u7EA6\u4E8C\u767E\u5C3A\uFF0C\u5899\u9876\u53EF\u5BB9\u516D\u8F86\u56DB\u9A6C\u6218\u8F66\u5E76\u9A7E\uFF1B\u552F\u6709\u74E6\u96F7\u5229\u4E9A\u65E7\u8840\u7EDF\u8005\u65B9\u53EF\u5C45\u4E8E\u5899\u5185\u3002"],["Circumference and thickness.","\u5468\u957F\u4E0E\u539A\u5EA6\u3002"],["Height scaled down to about 28 m; the oval plan, round towers and west gate are invented. The stone is not dragonglass.","\u9AD8\u5EA6\u7F29\u4E3A\u7EA628\u7C73\uFF1B\u692D\u5706\u5E73\u9762\u3001\u5706\u5854\u4E0E\u897F\u95E8\u5747\u4E3A\u81EA\u62DF\u3002\u5899\u77F3\u5E76\u975E\u9F99\u6676\u3002"]),"old-volantis":e(["Old Volantis","\u65E7\u57CE"],["The walled core on the east bank: palaces of the old Valyrian-blooded families, domes, slender towers and palm gardens.","\u4E1C\u5CB8\u5899\u5185\u7684\u65E7\u57CE\u6838\u5FC3\uFF1A\u74E6\u96F7\u5229\u4E9A\u65E7\u8840\u7EDF\u4E16\u5BB6\u7684\u5B85\u90B8\u3001\u7A79\u9876\u3001\u7EA4\u7EC6\u9AD8\u5854\u4E0E\u68D5\u6988\u5EAD\u56ED\u3002"],["Quiet, tall and rich: the old blood keep their houses here.","\u5B89\u9759\u3001\u9AD8\u8038\u3001\u5BCC\u5EB6\uFF0C\u65E7\u8840\u7EDF\u4E16\u5BB6\u4FBF\u5C45\u4E8E\u6B64\u3002"],"medium",["adwd","twoiaf"],["The Black Walls enclose the oldest part of the city, home of the old-blood families and closed to most outsiders.","\u9ED1\u5899\u73AF\u62B1\u7740\u57CE\u5E02\u6700\u53E4\u8001\u7684\u90E8\u5206\uFF0C\u662F\u65E7\u8840\u7EDF\u4E16\u5BB6\u7684\u5C45\u6240\uFF0C\u5916\u4EBA\u5927\u591A\u4E0D\u5F97\u5165\u5185\u3002"],["Street plan and architecture.","\u8857\u9053\u5E03\u5C40\u4E0E\u5EFA\u7B51\u98CE\u683C\u3002"],["Plastered, tile-roofed villas with blue-glazed domes on a raised plateau; wholly invented.","\u9AD8\u5730\u4E0A\u62B9\u7070\u74E6\u9876\u7684\u5B85\u90B8\uFF0C\u914D\u84DD\u91C9\u7A79\u9876\uFF1B\u7EAF\u5C5E\u81EA\u62DF\u3002"]),"triarchs-hall":e(["Triarchs' Hall","\u6267\u653F\u5B98\u5927\u5385"],["A domed, colonnaded hall imagined as the seat of the three triarchs.","\u4E00\u5EA7\u5706\u9876\u67F1\u5ECA\u5927\u5385\uFF0C\u8BBE\u60F3\u4E3A\u4E09\u4F4D\u6267\u653F\u5B98\u7406\u653F\u4E4B\u6240\u3002"],["Three triarchs rule, elected each year by the free landholders.","\u4E09\u4F4D\u6267\u653F\u5B98\u5171\u638C\u57CE\u90A6\uFF0C\u6BCF\u5E74\u7531\u62E5\u6709\u571F\u5730\u7684\u81EA\u7531\u6C11\u9009\u51FA\u3002"],"low",["adwd","twoiaf"],["Volantis is ruled by three triarchs elected annually by free landholders; the tiger and elephant factions contest the elections.","\u74E6\u5170\u63D0\u65AF\u7531\u4E09\u4F4D\u6267\u653F\u5B98\u7EDF\u6CBB\uFF0C\u6BCF\u5E74\u7531\u62E5\u6709\u571F\u5730\u7684\u81EA\u7531\u6C11\u9009\u4E3E\u4EA7\u751F\uFF1B\u864E\u515A\u4E0E\u8C61\u515A\u5728\u9009\u4E3E\u4E2D\u89D2\u9010\u3002"],["Where they meet and what the building looks like.","\u8BAE\u4E8B\u5730\u70B9\u4E0E\u5EFA\u7B51\u5F62\u8C8C\u3002"],["Entirely invented: a columned marble hall with a blue dome.","\u7EAF\u5C5E\u81EA\u62DF\uFF1A\u5927\u7406\u77F3\u67F1\u5ECA\u4E0E\u84DD\u8272\u7A79\u9876\u3002"]),"red-temple":e(["Red Temple","\u7EA2\u795E\u5E99"],["A huge red temple of R'hllor, guarded by the slave-soldiers of the Fiery Hand and said to be three times the size of the Great Sept of Baelor.","\u4F9B\u5949\u62C9\u8D6B\u6D1B\u7684\u5DE8\u5927\u7EA2\u8272\u795E\u5E99\uFF0C\u7531\u5974\u96B6\u58EB\u5175\u7EC4\u6210\u7684\u70C8\u7130\u4E4B\u624B\u5B88\u536B\uFF0C\u636E\u8BF4\u6709\u8D1D\u52D2\u5927\u5723\u5802\u7684\u4E09\u500D\u5927\u3002"],["Red walls and flame-topped spires: R'hllor has a vast following in Volantis.","\u7EA2\u5899\u4E0E\u706B\u7130\u822C\u7684\u5C16\u5854\uFF1A\u62C9\u8D6B\u6D1B\u5728\u74E6\u5170\u63D0\u65AF\u4FE1\u4F17\u6781\u591A\u3002"],"high",["adwd","awoiaf"],["A great red temple of R'hllor with a slave-soldier guard, the Fiery Hand; its high priest is Benerro; about three times the size of the Great Sept.","\u4E00\u5EA7\u5B8F\u5927\u7684\u62C9\u8D6B\u6D1B\u7EA2\u795E\u5E99\uFF0C\u5B88\u536B\u662F\u5974\u96B6\u58EB\u5175\u7EC4\u6210\u7684\u70C8\u7130\u4E4B\u624B\uFF1B\u5927\u796D\u53F8\u4E3A\u8D1D\u5185\u7F57\uFF1B\u89C4\u6A21\u7EA6\u4E3A\u8D1D\u52D2\u5927\u5723\u5802\u7684\u4E09\u500D\u3002"],["Its exact position and architecture.","\u786E\u5207\u4F4D\u7F6E\u4E0E\u5EFA\u7B51\u6837\u5F0F\u3002"],["A terraced red hall with eight tapering spires, placed inside the Black Walls; the novels seem to place it outside them, so position and form are invented.","\u68AF\u53F0\u5F0F\u7EA2\u8272\u6BBF\u5802\u914D\u516B\u5EA7\u6E10\u6536\u7684\u5C16\u5854\uFF0C\u7F6E\u4E8E\u9ED1\u5899\u4E4B\u5185\uFF1B\u5C0F\u8BF4\u4F3C\u4E4E\u5C06\u5176\u7F6E\u4E8E\u5899\u5916\uFF0C\u6545\u4F4D\u7F6E\u4E0E\u5F62\u5236\u5747\u4E3A\u81EA\u62DF\u3002"],["Benerro preaches that a long-awaited saviour has come in the east, and his followers grow restless.","\u8D1D\u5185\u7F57\u5BA3\u8BB2\u671F\u76FC\u5DF2\u4E45\u7684\u6551\u4E16\u4E3B\u5DF2\u5728\u4E1C\u65B9\u964D\u4E16\uFF0C\u4FE1\u4F17\u56E0\u6B64\u8E81\u52A8\u4E0D\u5B89\u3002"]),"western-quarters":e(["Western Quarters","\u897F\u5CB8\u57CE\u533A"],["The crowded, lower brick-and-ochre districts of the west bank, a sprawl of markets, warehouses and tenements.","\u897F\u5CB8\u4F4E\u77EE\u62E5\u6324\u7684\u7816\u7EA2\u4E0E\u8D6D\u8272\u57CE\u533A\uFF0C\u5E02\u573A\u3001\u4ED3\u5E93\u4E0E\u51FA\u79DF\u5C4B\u8FDE\u7EF5\u6210\u7247\u3002"],["Beyond the walls the city is a sea of small roofs and busy lanes.","\u9ED1\u5899\u4E4B\u5916\uFF0C\u662F\u5C0F\u5C4B\u9876\u4E0E\u7E41\u5FD9\u5DF7\u5F04\u6C47\u6210\u7684\u6D77\u6D0B\u3002"],"medium",["adwd","awoiaf"],["The western half across the Long Bridge is the newer, poorer side, where foreigners are largely confined.","\u957F\u6865\u53E6\u4E00\u7AEF\u7684\u897F\u534A\u57CE\u8F83\u65B0\u3001\u8F83\u7A77\uFF0C\u5916\u6765\u8005\u5927\u591A\u53EA\u80FD\u5728\u6B64\u6D3B\u52A8\u3002"],["Ward names, size and housing.","\u57CE\u533A\u540D\u79F0\u3001\u89C4\u6A21\u4E0E\u6C11\u5C45\u3002"],["Dense tile-and-brick houses; no street names or wards invented.","\u5BC6\u96C6\u7684\u7816\u74E6\u623F\u5C4B\uFF1B\u672A\u7F16\u9020\u8857\u540D\u6216\u57CE\u533A\u540D\u3002"]),"valyrian-road":e(["Valyrian Road","\u74E6\u96F7\u5229\u4E9A\u53E4\u9053"],["A dark paved road leaving the city, a fragment of the network of roads Valyria laid across Essos.","\u4E00\u6761\u5EF6\u4F38\u51FA\u57CE\u7684\u6DF1\u8272\u94FA\u77F3\u8DEF\uFF0C\u662F\u74E6\u96F7\u5229\u4E9A\u5F53\u5E74\u904D\u5E03\u5384\u7D22\u65AF\u7684\u9053\u8DEF\u7F51\u7684\u4E00\u6BB5\u3002"],["Paved by Valyria, roads like this still run out from Volantis across Essos.","\u8FD9\u7C7B\u7531\u74E6\u96F7\u5229\u4E9A\u94FA\u5C31\u7684\u9053\u8DEF\uFF0C\u81F3\u4ECA\u4ECD\u4ECE\u74E6\u5170\u63D0\u65AF\u901A\u5F80\u5384\u7D22\u65AF\u5404\u5730\u3002"],"low",["adwd","twoiaf"],[`Valyrian roads linked the Freehold's cities; the "demon road" runs east from Volantis toward Meereen.`,"\u74E6\u96F7\u5229\u4E9A\u53E4\u9053\u8FDE\u63A5\u81EA\u7531\u5821\u5792\u6CBB\u4E0B\u8BF8\u57CE\uFF1B\u201C\u6076\u9B54\u4E4B\u8DEF\u201D\u81EA\u74E6\u5170\u63D0\u65AF\u5411\u4E1C\u901A\u5F80\u5F25\u6797\u3002"],["Which roads leave the city, and from where.","\u6709\u54EA\u4E9B\u9053\u8DEF\u51FA\u57CE\uFF0C\u4ECE\u4F55\u5904\u51FA\u53D1\u3002"],["The road is drawn leaving to the west; its line and surface are invented and do not follow any described route.","\u573A\u666F\u4E2D\u9053\u8DEF\u5411\u897F\u51FA\u57CE\uFF1B\u8D70\u5411\u4E0E\u8DEF\u9762\u5747\u4E3A\u81EA\u62DF\uFF0C\u5E76\u4E0D\u5BF9\u5E94\u4E66\u4E2D\u4EFB\u4F55\u8DEF\u7EBF\u3002"])}};export{d as default};
